"""`Gag Mouth`: generated by export_nodes.py from face_cards.blend; kept by hand from then on."""

NAME = 'Gag Mouth'


def build(lib):
    t = lib.new_material(NAME, props={
            'surface_render_method': 'BLENDED',
            'blend_method': 'BLEND',
            'use_backface_culling': True,
        })

    t.node('ShaderNodeEmission', 'Emission', props={
        'location': (-300.0, -100.0),
    })
    t.node('ShaderNodeBsdfTransparent', 'Transparent BSDF', props={
        'location': (-300.0, 100.0),
    })
    t.node('ShaderNodeMixShader', 'Mix Shader', props={
        'location': (-50.0, 0.0),
    })
    t.node('ShaderNodeOutputMaterial', 'Material Output', props={
        'location': (200.0, 0.0),
    })
    t.node('ShaderNodeGroup', 'Group', inputs={'Mouth': 'Drool 6'}, props={
        'node_tree': lib.group('Gag Mouth Atlas'),
        'location': (-600.0, 0.0),
        'width': 200.0,
        'label': 'Gag Mouth Atlas',
    })

    t.link('Transparent BSDF', 'BSDF', 'Mix Shader', 'Shader')
    t.link('Emission', 'Emission', 'Mix Shader', 'Shader_001')
    t.link('Mix Shader', 'Shader', 'Material Output', 'Surface')
    t.link('Group', 'Color', 'Emission', 'Color')
    t.link('Group', 'Alpha', 'Mix Shader', 'Fac')
    return t
